"""Minimum-norm two-step affine router with frozen weekly behavior."""
import datetime as _dt


def season(freq):
    f = str(freq).lower()
    if "min" in f or "sec" in f: return None
    for k, p in (("hour", 24), ("week", 52), ("w", 52), ("month", 12), ("day", 7), ("d", 7)):
        if k in f: return p
    return None


def seasonal(h, H, p):
    return [h[-p + i] if p and len(h) >= p and -p + i < 0 else h[-1] for i in range(H)]


def blend(members, w, s, last):
    return [(1 - s) * sum(wi * m[i] for wi, m in zip(w, members)) + s * last for i in range(len(members[0]))]


def _d(s):
    try: return _dt.date.fromisoformat(str(s)[:10])
    except Exception: return None


def _correction_multipliers(view):
    H = view["H"]
    fut = [_d(t) for t in view.get("future_timestamps") or []]
    fut = [d for d in fut if d]
    events = [(doc["document_id"], e) for doc in view.get("documents") or []
              for e in doc.get("events") or []
              if e.get("direction") in ("up", "down") and (e.get("confidence") or 0) >= 0.6]
    dated = [d for _, e in events for d in (_d(e.get("time_start")), _d(e.get("time_end"))) if d]
    if fut: dated = [d for d in dated if d < fut[0]]
    anchor = max(dated) if dated else None
    recent_days = 14 if any(k in str(view["freq"]).lower() for k in ("d", "w")) and "month" not in str(view["freq"]).lower() else 45
    mult = [1.0] * H
    for _, e in events:
        sign = 1 if e["direction"] == "up" else -1
        conf = float(e["confidence"])
        t0, t1 = _d(e.get("time_start")), _d(e.get("time_end"))
        window = None
        if fut and t0:
            end = t1 or t0
            idx = [i for i, d in enumerate(fut) if t0 <= d <= end]
            if idx: window = (min(idx), max(idx) + 1)
        if window:
            start, end, step = window[0], window[1], 0.05
        else:
            last = t1 or t0
            if not (anchor and last and (anchor - last).days <= recent_days and (not fut or last < fut[0])):
                continue
            start, end, step = 0, max(1, -(-H // 3)), 0.03
        m = 1 + sign * step * conf
        for i in range(max(0, int(start)), min(H, int(end))): mult[i] *= m
    return [max(0.9, min(1.1, m)) for m in mult]


